Lemma pf_L4 : forall (k : nat) (u c : Z)
    rax spx gp tp t2 s0 a3 a4 a5 a6 s3 s4 s6 s7 s8 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (p0 : Z) (bs : list byte) (L : Z) (bc : byte),
  bytes_at asegs m1 p0 bs -> accessible m1 p0 (Z.of_nat (length bs)) -> L = p0 + Z.of_nat (length bs) -> L < 2^64 ->
  p0 <= u < L -> (Z.to_nat (L - u) <= k)%nat -> nth_error bs (Z.to_nat (u - p0)) = Some bc -> zb bc = c ->
  evt asegs (fun ms' =>
       (* [comment removed for export] *)
       (exists a2' a3', ms' = MS (pf_L4_regs rax spx gp tp t2 s0 (wz L) (wz L) a2' a3' a4 a5 a6 s3 s4 L s6 s7 s8 s10 s11 t3 t4 t5 t6)
                                F (Z_to_bv 64 0xd0d84) fc None m1 (seg_rom asegs))
    \/ (* [comment removed for export] *)
       (exists a0' a1' a2' a3', ms' = MS (pf_L4_regs rax spx gp tp t2 s0 a0' a1' a2' a3' a4 a5 a6 s3 s4 L s6 s7 s8 s10 s11 t3 t4 t5 t6)
                                        F (Z_to_bv 64 0xd0fc0) fc None m1 (seg_rom asegs))
    \/ (* [comment removed for export] *)
       (exists u' (b' : byte) a3', ms' = MS (pf_L4_regs rax spx gp tp t2 s0 (wz (u' + 1)) (wz (u' + 1)) (wz 13) a3' a4 a5 a6 s3 s4 L s6 s7 s8 s10 s11 t3 t4 t5 t6)
                                   F (Z_to_bv 64 0xd0ec4) fc None m1 (seg_rom asegs)
           /\ u <= u' < L /\ nth_error bs (Z.to_nat (u' - p0)) = Some b' /\ zb b' = 13))
    (MS (pf_L4_regs rax spx gp tp t2 s0 (wz (u + 1)) (wz (u + 1)) (wz c) a3 a4 a5 a6 s3 s4 L s6 s7 s8 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xd0d3c) fc None m1 (seg_rom asegs)).
